mapper.insert:
WITH upsert AS ( UPDATE biz04_provide_setup
                    SET biz04_company_id         = #{companyId}
                      , biz04_provide_content_cd = #{req.provideContentCode}
                      , biz04_emp_set_yn         = #{req.empSetYn}
                  WHERE biz04_provide_setup_id = #{req.provideSetupId}
                 RETURNING *
) INSERT
    INTO biz04_provide_setup
  SELECT f_create_seq()
       , #{companyId}
       , #{req.provideContentCode}
       , #{req.empSetYn}
   WHERE NOT EXISTS ( SELECT * from upsert )
